from flask import current_app, jsonify, request


def error_response(message, status_code=400, errors=None):
    payload = {"error": message}
    if errors:
        payload["details"] = errors
    return jsonify(payload), status_code


def paginate_query(query, serializer):
    try:
        page = int(request.args.get("page", 1))
    except (TypeError, ValueError):
        page = 1
    try:
        per_page = int(request.args.get("per_page", current_app.config["DEFAULT_PAGE_SIZE"]))
    except (TypeError, ValueError):
        per_page = current_app.config["DEFAULT_PAGE_SIZE"]

    page = max(page, 1)
    per_page = min(max(per_page, 1), current_app.config["MAX_PAGE_SIZE"])

    pagination = query.paginate(page=page, per_page=per_page, error_out=False)

    return {
        "items": [serializer(item) for item in pagination.items],
        "pagination": {
            "page": pagination.page,
            "per_page": pagination.per_page,
            "total_items": pagination.total,
            "total_pages": pagination.pages,
            "has_next": pagination.has_next,
            "has_prev": pagination.has_prev,
        },
    }

from flask import Flask

from app.config import config_by_name
from app.extensions import db, jwt, migrate


def create_app(config_name="development"):
    app = Flask(__name__)
    app.config.from_object(config_by_name[config_name])

    db.init_app(app)
    jwt.init_app(app)
    migrate.init_app(app, db)

    from app.auth.routes import auth_bp
    from app.categories.routes import categories_bp
    from app.tasks.routes import tasks_bp

    app.register_blueprint(auth_bp, url_prefix="/api/auth")
    app.register_blueprint(categories_bp, url_prefix="/api/categories")
    app.register_blueprint(tasks_bp, url_prefix="/api/tasks")

    register_error_handlers(app)
    register_jwt_callbacks(jwt)

    @app.get("/api/health")
    def health():
        return {"status": "ok"}

    return app


def register_error_handlers(app):
    from app.utils import error_response

    @app.errorhandler(404)
    def not_found(e):
        return error_response("Resource not found", 404)

    @app.errorhandler(405)
    def method_not_allowed(e):
        return error_response("Method not allowed", 405)

    @app.errorhandler(500)
    def server_error(e):
        return error_response("Internal server error", 500)


def register_jwt_callbacks(jwt_manager):
    from app.utils import error_response

    @jwt_manager.unauthorized_loader
    def missing_token(reason):
        return error_response(f"Missing or invalid authorization token: {reason}", 401)

    @jwt_manager.invalid_token_loader
    def invalid_token(reason):
        return error_response(f"Invalid token: {reason}", 401)

    @jwt_manager.expired_token_loader
    def expired_token(jwt_header, jwt_payload):
        return error_response("Token has expired", 401)

    @jwt_manager.revoked_token_loader
    def revoked_token(jwt_header, jwt_payload):
        return error_response("Token has been revoked", 401)

import re

from flask import Blueprint, jsonify, request
from flask_jwt_extended import (
    create_access_token,
    create_refresh_token,
    get_jwt_identity,
    jwt_required,
)

from app.extensions import db
from app.models import User
from app.utils import error_response

auth_bp = Blueprint("auth", __name__)

EMAIL_RE = re.compile(r"^[^@\s]+@[^@\s]+\.[^@\s]+$")


def validate_registration(data):
    errors = {}
    username = (data.get("username") or "").strip()
    email = (data.get("email") or "").strip()
    password = data.get("password") or ""

    if len(username) < 3:
        errors["username"] = "Username must be at least 3 characters long"
    if not EMAIL_RE.match(email):
        errors["email"] = "A valid email address is required"
    if len(password) < 8:
        errors["password"] = "Password must be at least 8 characters long"

    return errors


@auth_bp.post("/register")
def register():
    data = request.get_json(silent=True) or {}
    errors = validate_registration(data)
    if errors:
        return error_response("Validation failed", 422, errors)

    username = data["username"].strip()
    email = data["email"].strip().lower()

    if User.query.filter_by(username=username).first():
        return error_response("Username already taken", 409)
    if User.query.filter_by(email=email).first():
        return error_response("Email already registered", 409)

    user = User(username=username, email=email)
    user.set_password(data["password"])
    db.session.add(user)
    db.session.commit()

    access_token = create_access_token(identity=str(user.id))
    refresh_token = create_refresh_token(identity=str(user.id))

    return jsonify(
        {
            "user": user.to_dict(),
            "access_token": access_token,
            "refresh_token": refresh_token,
        }
    ), 201


@auth_bp.post("/login")
def login():
    data = request.get_json(silent=True) or {}
    username_or_email = (data.get("username") or data.get("email") or "").strip()
    password = data.get("password") or ""

    if not username_or_email or not password:
        return error_response("Username/email and password are required", 400)

    user = User.query.filter(
        (User.username == username_or_email) | (User.email == username_or_email.lower())
    ).first()

    if not user or not user.check_password(password):
        return error_response("Invalid credentials", 401)

    access_token = create_access_token(identity=str(user.id))
    refresh_token = create_refresh_token(identity=str(user.id))

    return jsonify(
        {
            "user": user.to_dict(),
            "access_token": access_token,
            "refresh_token": refresh_token,
        }
    ), 200


@auth_bp.post("/refresh")
@jwt_required(refresh=True)
def refresh():
    identity = get_jwt_identity()
    access_token = create_access_token(identity=identity)
    return jsonify({"access_token": access_token}), 200


@auth_bp.get("/me")
@jwt_required()
def me():
    identity = get_jwt_identity()
    user = db.session.get(User, int(identity))
    if not user:
        return error_response("User not found", 404)
    return jsonify(user.to_dict()), 200

